import { CAPABILITIES_ADDITIONAL_1 } from '../completion/capabilitiesAdditional1.js';
import { CAPABILITIES_ADDITIONAL_2 } from '../completion/capabilitiesAdditional2.js';
import { area, beam, buff, cleanse, defend, guard, heal, hit, shot } from './rules.js';

// Three explicit actions per ID. Shared helpers supply numerical shapes, while
// the completed identity supplies bibliography; neither selects an action.
const sources = { ...CAPABILITIES_ADDITIONAL_1, ...CAPABILITIES_ADDITIONAL_2 };
const kit = (id, simple, secondary, defense, reference) => {
  const source = sources[id];
  return {
    universe: source.universe,
    sourceWork: source.sourceWork,
    sourceReference: `${source.sourceReference} Base/secondary/defense: ${reference}`,
    sourceUrl: source.sourceUrl || source.referenceUrl || null,
    identityBasis: source.identityBasis === 'authored-universe-canon' ? 'authored-universe-canon' : 'canonical-role',
    canonicalVerified: false,
    networkVerified: false,
    gameplayAdaptation: true,
    simple,
    secondary: { cd: 6, ...secondary },
    defense
  };
};

